    a = action.strip().lower()
    if a.startswith("no ") or a.startswith("warning:") or a.startswith("c2patool available"):
        return False
    if a.startswith("deep image pass not needed") or a.startswith("kept "):
        return False
    return not (" skipped" in a or " failed" in a)

def _spread_indices(total: int, k: int) -> list[int]:
    """Return *k* 0-based indices evenly spread across *total* frames, deduped."""
    if k <= 0 or total <= 0:
        return []
    if k >= total:
        return list(range(total))
    if k == 1:
        return [0]
    indices: list[int] = []
    for i in range(k):
        indices.append(round(i * (total - 1) / (k - 1)))
    seen: set[int] = set()
    out: list[int] = []
    for idx in indices:
        if idx not in seen:
            seen.add(idx)
            out.append(idx)
    return out

