def _sanitize_sample(obj: object) -> object:
    """Keep structure; drop long arrays and obvious secret-like strings."""
    if isinstance(obj, dict):
        out = {}
        for k, v in obj.items():
            lk = str(k).lower()
            if any(s in lk for s in ("key", "token", "secret", "password", "authorization")):
                out[k] = "***"
            else:
                out[k] = _sanitize_sample(v)
        return out
    if isinstance(obj, list):
        if len(obj) > 3:
            return [_sanitize_sample(x) for x in obj[:3]] + [f"...(+{len(obj) - 3} more)"]
        return [_sanitize_sample(x) for x in obj]
    if isinstance(obj, str) and len(obj) > 120:
        return obj[:120] + "..."
    return obj

def merge_pairs(merges):
    """Normalise merges to (left, right) and reject a repeated pair."""
    pairs, seen = [], {}
    for rank, merge in enumerate(merges):
        left, right = merge.split(" ", 1) if isinstance(merge, str) else merge
        if (left, right) in seen:
            raise SystemExit(
                f"merges {seen[(left, right)]} and {rank} are both "
                f"{left!r} + {right!r}; one pair cannot have two ranks"
            )
        seen[(left, right)] = rank
        pairs.append((left, right))
    return pairs

def record_tag(r):
    """Tag as recorded, or as embedded in the run name."""
    if "tag" in r:
        return r["tag"] or ""
    name = r.get("name", "")
    arm = r.get("arm", "")
    if name.startswith(arm + "-"):
        rest = name[len(arm) + 1:]
        return rest.rsplit("-s", 1)[0] if "-s" in rest else ""
    return ""

def make_tileable_rgb(payload: bytes, size: int, blend_fraction: float = 0.08) -> bytes:
    """Blend opposite border pairs so repeated offline maps do not expose hard seams."""
    if len(payload) != size * size * 3:
        raise ValueError("tileable RGB payload has the wrong size")
    output = bytearray(payload)
    blend = max(1, min(size // 4, round(size * blend_fraction)))

    def blend_pair(first: int, second: int, weight: float) -> None:
        for channel in range(3):
            average = (output[first + channel] + output[second + channel]) * 0.5
            output[first + channel] = round(output[first + channel] * (1 - weight) + average * weight)
            output[second + channel] = round(output[second + channel] * (1 - weight) + average * weight)

    for offset in range(blend):
        weight = 1 - offset / blend
        for y in range(size):
            left = (y * size + offset) * 3
            right = (y * size + size - 1 - offset) * 3
            blend_pair(left, right, weight)
        for x in range(size):
            top = (offset * size + x) * 3
            bottom = ((size - 1 - offset) * size + x) * 3
            blend_pair(top, bottom, weight)
    return bytes(output)

def blind_scout_phase_id(pass_id: str) -> str:
    """Map legacy pass aliases to the four user-facing phase scopes."""

    normalized = str(pass_id or "").strip().lower()
    if normalized in {"blockout", "structure", "structural-pass"}:
        return "blockout"
    if normalized in {"form", "form-refinement"}:
        return "form"
    if normalized in {"lookdev", "material-pass", "surface-pass", "lighting-pass"}:
        return "lookdev"
    if normalized in {"interaction", "interaction-pass"}:
        return "interaction"
    return normalized
